/**
 * 톡사르 지형광 테마 데이터 — 오염 늪. 지형 저지를 흐르는 **독성 발광 개천**이 유일한 광원이다.
 *
 * ## 왜 카르곤과 같은 가산 발광 구조가 여기서도 성립하는가
 * 이 레이어의 메커니즘은 "지형 필드의 등고선을 따라 흐르는 띠"이고, 흐르는 것이 용암인지
 * 침출수인지는 기하와 무관하다. 톡사르에서 성립하는 근거는 셋이다:
 *  1. **경계가 곧 물길이다.** 오염수는 고지에서 저지로 흘러 지형 경계를 따라 고인다 —
 *     마칭 스퀘어즈가 뽑는 자취가 그대로 개천의 자취다.
 *  2. **자체 발광이다.** 생물 발광이든 방사든, 개천이 스스로 빛나므로 `add` 합성이 맞다.
 *     빛나지 않는 물이라면 반사(=주변광 필요)라 이 구조 자체가 틀렸을 것이다.
 *  3. **세기에 지역 편차가 있다.** 오염은 번지므로 "지금 살아 있는 구간"과 "식은 구간"이
 *     나뉜다 — `intensity` 의 지역 필드 + 잔열 하한이 그대로 대응한다.
 *
 * 반대로 카르곤에서 가져오면 안 되는 것도 분명하다: 열기 기둥은 "뜨거우니까 위로 솟는" 기하지만
 * 늪 가스는 **부력이 약해 낮게 퍼진다**(아래 `plume` 참조).
 *
 * ## 색상각 — 이 행성만 위험원이 셋이다
 * 안전 골짜기는 `computeSafeHueWindows(FOREGROUND_SIGNAL_COLORS, 10)` 결과 **280.19°→305.00°**
 * 하나뿐이다(폭 24.81°). 그런데 계약이 재지 않는 위험원이 하나 더 있다 — **톡사르 적
 * 스프라이트 몸통색이 281.6°·283.1° 로 그 골짜기 안이다**(`enemy_toxar_gunner` rgb 138,52,176 /
 * 나머지 3종 rgb 230,184,248). `FOREGROUND_SIGNAL_COLORS` 는 탄·아군 표식만 담으므로
 * 검증기는 이걸 통과시킨다.
 *
 * 그래서 팔레트를 골짜기 **중앙(292.6°)이 아니라 마젠타 쪽(293.2~299.3°)** 에 몰았다:
 *
 * | 위험원 | 각도 | 팔레트와의 최소 거리 |
 * |---|---|---|
 * | 퍼플 적탄 | 270.19° | 23.0° |
 * | 적 몸통 | 281.6·283.1° | **10.1°** |
 * | 마젠타 적탄 | 315.00° | 15.7° |
 *
 * 중앙에 뒀다면 적 몸통과 9.5° 였을 자리다. **가장 가까운 위험원까지의 거리를 최대화**한 지점이
 * 여기이며, 좁은 골짜기에서 채도를 낮춰 도망가는 것은 해가 아니다 — 가산 합성에서 저채도는
 * 흰색 포화로 직결돼 흰 코어 탄과 오히려 더 닮아진다. 분리는 반드시 색상각으로 한다.
 *
 * ## 명도 — 이 행성에서 심지를 밝히는 것은 위장을 만드는 방향이다
 * 적 4종 중 3종이 휘도 198 의 밝은 라벤더다. 그래서 심지 색을 카르곤(0xff6d33 계열, 휘도 130+)
 * 만큼 올리지 않고, 대신 G 채널을 비워 둔다 — 그 밝은 적과의 **유일한 분리 채널이 G** 이기
 * 때문이다(예: 심지 0xe760ee 와 적 rgb(230,184,248) 의 채널차는 R 1 · B 10 인데 G 가 88 이다).
 */

import type { TerrainLightTheme } from '../../contracts/terrainLight.js';

export const TOXAR_TERRAIN_LIGHT: TerrainLightTheme = {
  themeId: 'toxar',

  /**
   * 개천 색 4종. 전부 색상각 `[293.2°, 299.3°]` 안이다 — 위 표의 세 위험원에서 동시에 가장
   * 멀리 떨어지는 대역이다. G 를 낮게 유지해 두 심지가 이음매에서 겹쳐도 R·B 만 클리핑한다
   * (= 흰색이 아니라 진한 자홍).
   */
  channel: [
    { glow: 0xc51cce, core: 0xe760ee },
    { glow: 0xbc1ac8, core: 0xde58ea },
    { glow: 0xd028d2, core: 0xee66f0 },
    { glow: 0xb818c6, core: 0xde48ea },
  ],

  /**
   * 지각(이끼 회록)이 중간 밝기로 뜨면 라벤더 적이 위장된다. 카르곤(0.38)보다 낮은 0.34 인
   * 이유는 톡사르 지각 자체가 이미 더 어둡기 때문이다(프리뷰 상부 평균 L 40.3 vs 카르곤 43.1).
   * 틴트는 완전 회색이 아니라 살짝 녹빛이어서 늪이 차갑게 죽지 않는다.
   */
  dusk: { alpha: 0.34, tint: 0x3e4a3a },

  /** 개천은 용암보다 얕고 넓게 번진다 — 폭은 카르곤(104)보다 넓히고 상한은 낮췄다. */
  glow: { alphaCap: 0.36, width: 112, profileExp: 2.2 },
  /**
   * 심지는 반대로 더 좁고 더 날카롭다(카르곤 17/6.2 → 15/6.6). 넓은 겹을 넓히고 좁은 겹을
   * 좁힌 것은 같은 총 광량을 **중간 밝기 면적이 아니라 첨두**로 쓰기 위해서다 — 중간 밝기
   * violet 이 이 행성 적의 서식지다.
   */
  core: { alphaCap: 0.72, width: 15, profileExp: 6.6 },

  /**
   * 폭 15 는 화면 배율 ≈0.91 에서 ≈14 화면 px 다. 상용(Dead Cells·Hades)의 4~8px 보다 넓지만
   * 이 게임의 지형 덩어리가 화면의 3~5할을 차지해 같은 *상대* 두께를 맞추려면 이 정도가 필요하다.
   * 틴트가 회록인 것은 늪 그늘이 이끼 색이기 때문이다.
   */
  ao: {
    alphaCap: 0.64,
    tint: 0x4a5244,
    width: 15,
    offset: 14,
    plateau: 0.5,
    falloffExp: 2.6,
    floor: 0.6,
  },

  /** 틴트가 AO 보다 옅다 — 캐스트 섀도는 접지 어둠보다 항상 밝다. */
  shadow: { alphaCap: 0.48, tint: 0x4e564a, width: 54, offset: 38, minStrength: 0.12 },

  /** 296.9° — 창 안에서 가장 저채도 = 가장 "젖은 이끼"에 가깝다. */
  rim: { alphaCap: 0.48, color: 0xc47ac8, width: 11, widthFloor: 0.5, offset: -16, minStrength: 0.18 },

  /**
   * 늪 가스 — 카르곤 열기 기둥의 자리이되 **기하가 다르다.** 열기는 뜨거워서 세로로 길게
   * 솟지만(stretch 1.55 · rise 92), 늪 가스는 부력이 약해 수면 위에 낮게 눌려 퍼진다:
   * `stretch` 1.25 로 등방에 가깝고 `rise` 70 으로 덜 뜬다. 대신 `width` 를 160 으로 넓혀
   * "낮고 넓은 층"이 되게 했다. `rise` 가 양수인 것(위로 자란다)은 여전히 맞다 — 가스이므로.
   */
  plume: {
    alphaCap: 0.16,
    color: 0xa614b4,
    width: 160,
    stretch: 1.25,
    rise: 70,
    profileExp: 2.2,
    minStrength: 0.6,
  },

  /**
   * 지역 필드 9타일(=576px)은 1920×1080(≈30×17타일) 화면 안에 활성 오염 덩어리가 서너 개
   * 들어가는 크기다. 카르곤(8)보다 조금 크게 잡은 이유는 오염이 용암보다 넓게 번지는
   * 서사이기 때문이고, 더 키우면 한 화면이 통째로 오염이거나 통째로 식어 지역 편차가 사라진다.
   *
   * `emberMin` 0.30 은 "번짐이 지나갔지만 아직 남아 있는 자국"으로 읽히는 대역이다 —
   * 여기서 헤일로 실효 알파 ≈0.108, 심지 ≈0.216 이라 붕괴선(0.08) 위에 있다.
   */
  intensity: {
    regionTiles: 9,
    regionThreshold: 0.52,
    regionSpan: 0.16,
    emberMin: 0.3,
    emberMax: 0.5,
    emberModTiles: 3.6,
    emberRemapLo: 0.32,
    emberRemapHi: 0.68,
    widthBase: 0.5,
    widthGain: 0.5,
  },
};
